def sanitize_filename_windows(name):
    reserved = '<>:"/\\|?*'
    cleaned = "".join("_" if c in reserved else c for c in name)
    return cleaned.rstrip(" .")

def collapse_underscores(name):
    out = []
    prev_underscore = False
    for c in name:
        if c == "_":
            if not prev_underscore:
                out.append(c)
            prev_underscore = True
        else:
            out.append(c)
            prev_underscore = False
    return "".join(out).strip("_")

def dedupe_extension(name):
    parts = name.split(".")
    if len(parts) >= 3 and parts[-1] == parts[-2] and parts[-1] != "":
        return ".".join(parts[:-1])
    return name

def safe_slug_filename(name, max_len):
    out = []
    prev_dash = False
    for c in name.lower():
        if c.isalnum():
            out.append(c)
            prev_dash = False
        else:
            if not prev_dash:
                out.append("-")
            prev_dash = True
    slug = "".join(out).strip("-")
    slug = slug[:max_len]
    slug = slug.rstrip("-")
    return slug
